  ["ab3ff2b4ad9ebce1"] = { "L'⟦Alliance=Alleanza⟧ ha conquistato la ⟦Coldtooth Mine=Miniera di Dentefreddo⟧!", "." },
  ["ab4a926d92c863bd"] = { "Addio.", "." },
  ["ab4baf5863a4a780"] = { "Questo qui è il mezzo di trasporto più raffinato e all'avanguardia che il denaro possa costruire. Cosa? Il ⟦Deeprun Tram=Tram degli Abissi⟧? Gli gnomi? Senti, amico, se credi a quelle fesserie ho una statua giù a Rovotorto da venderti. Allora, vai a Grom'gol a piedi o viaggi con stile su questa splendida macchina volante? Scegli tu.", "." },
  ["ab4ed848ec051906"] = { "Su, su, {name}, non preoccuparti! Quale pezzo dell'amuleto hai smarrito?\n\nHai controllato tutte le tue borse e la banca?", "." },
  ["ab579a5fb79734c2"] = { "Ah, quindi è così. Sei <benvenuto/benvenuta> a ⟦Ironforge=Forgiardente⟧, {class}. \r\n\nQuesta città è la sede del clan Barbabronzea. Siamo un popolo antico e fiero, e i nostri artigiani non sono secondi a nessuno. Non troverai creazioni in metallo o in pietra più raffinate di quelle di fattura nanica.\r\n\nSiamo anche tra i più audaci esploratori di Azeroth. Se hai il gusto dell'avventura, ti troverai in buona compagnia tra la nostra gente.\r\n\nGrazie per aver parlato con me, {name}. Ora va' con la benedizione del clan Barbabronzea. \r\n\nAuguro ogni bene a te e alla tua gente.", "." },
  ["ab593ca5d68421b4"] = { "Osi mettere piede sul suolo sacro degli Hakkari? Servitori di Hakkar, distruggete gli infedeli!", "." },
