  ["ab916f510b8ff8d1"] = { "Manca 1 minuto all'inizio della battaglia per la ⟦Alterac Valley=Valle d'Alterac⟧.", "." },
  ["aba3dbe111642bf7"] = { "Puoi darmi delle indicazioni?", "." },
